/**
 * SafeSteps PDF Generator: Doctor Visit Summary (A4)
 *
 * Capabilities:
 * - Clean A4 document layout matching the Stitch Visit Summary specifications.
 * - Sticker-free, clinical black/teal/slate styling suitable for GP clinic printing.
 * - Embeds TrueType fonts for Tamil (NotoSansTamil) and Hindi (NotoSansDevanagari).
 * - Always includes the required clinical footer:
 *   "Generated by SafeSteps. General information only, not a medical record or diagnosis."
 */

import PDFDocument from "pdfkit";
import { VisitSummary, PatientDetails, ConversationRecord } from "./summary";
import { setupPdfFonts, getFontForText } from "./pdfFonts";

export async function generateVisitSummaryPdf(
  summary: VisitSummary,
  conversation: ConversationRecord,
  patientDetails: PatientDetails
): Promise<Buffer> {
  return new Promise((resolve, reject) => {
    try {
      const doc = new PDFDocument({
        size: "A4",
        margins: { top: 36, bottom: 40, left: 40, right: 40 },
        info: {
          Title: `SafeSteps Doctor Visit Summary - ${conversation.title}`,
          Author: "SafeSteps AI Clinical Guidance",
          Subject: "Clinical Consultation Summary for Primary Care",
        },
      });

      const chunks: Buffer[] = [];
      doc.on("data", (chunk: Buffer) => chunks.push(chunk));
      doc.on("end", () => resolve(Buffer.concat(chunks)));
      doc.on("error", (err) => reject(err));

      const fonts = setupPdfFonts(doc, conversation.language);

      const pageWidth = 595.28;
      const contentWidth = pageWidth - 80; // 40 left + 40 right margin

      // 1. Header: Brand Logo & Title
      doc
        .font(getFontForText("SafeSteps", fonts, true))
        .fontSize(18)
        .fillColor("#0f766e")
        .text("SafeSteps", 40, 36, { continued: true })
        .font(fonts.regular)
        .fontSize(10)
        .fillColor("#64748b")
        .text("   CLINICAL GUIDANCE SUPPORT");

      // Consultation ID and Date in Top Right
      const consultationRef = `#SF-${conversation.id
        .replace(/-/g, "")
        .substring(0, 5)
        .toUpperCase()}`;

      const formattedDate = new Date(conversation.created_at).toLocaleDateString(
        "en-GB",
        {
          day: "numeric",
          month: "short",
          year: "numeric",
        }
      );

      doc
        .font(fonts.bold)
        .fontSize(9)
        .fillColor("#334155")
        .text(`Consultation ID: ${consultationRef}`, 40, 38, {
          align: "right",
          width: contentWidth,
        })
        .font(fonts.regular)
        .fontSize(8)
        .fillColor("#64748b")
        .text(`Date: ${formattedDate}`, 40, 50, {
          align: "right",
          width: contentWidth,
        });

      // Divider Line
      doc
        .strokeColor("#e2e8f0")
        .lineWidth(1)
        .moveTo(40, 68)
        .lineTo(pageWidth - 40, 68)
        .stroke();

      // Document Title
      let y = 78;
      doc
        .font(fonts.bold)
        .fontSize(15)
        .fillColor("#0f172a")
        .text("Visit summary for your doctor", 40, y);

      y += 20;
      doc
        .font(fonts.regular)
        .fontSize(8.5)
        .fillColor("#64748b")
        .text(
          "Structured clinical intake summary prepared by the patient via SafeSteps to assist medical consultation.",
          40,
          y
        );

      y += 18;

      // 2. Patient Profile Box (Bordered Box)
      const profileBoxY = y;
      doc
        .rect(40, profileBoxY, contentWidth, 70)
        .fillAndStroke("#f8fafc", "#cbd5e1");

      doc
        .font(fonts.bold)
        .fontSize(8.5)
        .fillColor("#0f766e")
        .text("PATIENT INFORMATION & RELEVANT BACKGROUND", 48, profileBoxY + 8);

      doc
        .font(fonts.regular)
        .fontSize(7.5)
        .fillColor("#94a3b8")
        .text(
          patientDetails.personaliseEnabled
            ? "Self-reported & Profile Verified"
            : "Privacy Protected",
          40,
          profileBoxY + 8,
          { align: "right", width: contentWidth - 8 }
        );

      if (patientDetails.personaliseEnabled) {
        // Col 1: Name, Age, Sex
        const col1X = 48;
        const col1Y = profileBoxY + 24;
        const nameText = patientDetails.fullName || "Patient";
        doc
          .font(getFontForText(nameText, fonts, true))
          .fontSize(9.5)
          .fillColor("#0f172a")
          .text(nameText, col1X, col1Y);

        const ageSex = [
          patientDetails.age ? `Age: ${patientDetails.age}` : null,
          patientDetails.sex ? `Sex: ${patientDetails.sex}` : null,
        ]
          .filter(Boolean)
          .join(" • ");

        doc
          .font(fonts.regular)
          .fontSize(8)
          .fillColor("#475569")
          .text(ageSex || "Adult", col1X, col1Y + 14);

        // Col 2: Allergies
        const col2X = 210;
        doc
          .font(fonts.bold)
          .fontSize(8)
          .fillColor("#dc2626")
          .text("Known Allergies:", col2X, col1Y);

        const allergyStr =
          patientDetails.allergies.length > 0
            ? patientDetails.allergies.join(", ")
            : "No known drug allergies reported";

        doc
          .font(getFontForText(allergyStr, fonts))
          .fontSize(8)
          .fillColor("#334155")
          .text(allergyStr, col2X, col1Y + 12, { width: 160 });

        // Col 3: Conditions & Medicines
        const col3X = 380;
        doc
          .font(fonts.bold)
          .fontSize(8)
          .fillColor("#0f766e")
          .text("Conditions & Regular Medicines:", col3X, col1Y);

        const condMed = [
          patientDetails.conditions.length > 0
            ? patientDetails.conditions.join(", ")
            : "None reported",
          patientDetails.medicines.length > 0
            ? `Meds: ${patientDetails.medicines.join(", ")}`
            : null,
        ]
          .filter(Boolean)
          .join(" | ");

        doc
          .font(getFontForText(condMed, fonts))
          .fontSize(8)
          .fillColor("#334155")
          .text(condMed, col3X, col1Y + 12, { width: 170 });
      } else {
        doc
          .font(fonts.regular)
          .fontSize(8.5)
          .fillColor("#64748b")
          .text(
            patientDetails.disclaimerNote ||
              "Patient details withheld (Personalisation is disabled in your profile privacy settings).",
            48,
            profileBoxY + 32,
            { width: contentWidth - 16 }
          );
      }

      y = profileBoxY + 78;

      // 3. Section 1: What I told SafeSteps (Symptoms & Timeline)
      doc
        .font(fonts.bold)
        .fontSize(10.5)
        .fillColor("#0f172a")
        .text("1. What I told SafeSteps (Symptoms & Timeline)", 40, y);

      y += 16;

      for (const sym of summary.symptoms) {
        const symTitle = `${sym.name}${
          sym.duration && sym.duration !== "Not specified"
            ? ` — Duration: ${sym.duration}`
            : ""
        }`;

        doc
          .font(getFontForText(symTitle, fonts, true))
          .fontSize(9)
          .fillColor("#0f766e")
          .text(`• ${symTitle}`, 48, y);

        y += 12;

        if (sym.details) {
          doc
            .font(getFontForText(sym.details, fonts))
            .fontSize(8.5)
            .fillColor("#334155")
            .text(sym.details, 58, y, { width: contentWidth - 28 });
          y += doc.heightOfString(sym.details, { width: contentWidth - 28 }) + 6;
        }
      }

      y += 6;

      // 4. Section 2: Questions SafeSteps Asked & Patient Responses
      if (summary.keyAnswers && summary.keyAnswers.length > 0) {
        doc
          .font(fonts.bold)
          .fontSize(10.5)
          .fillColor("#0f172a")
          .text("2. Questions SafeSteps Asked & Patient Responses", 40, y);

        y += 16;

        for (const ka of summary.keyAnswers) {
          const qFont = getFontForText(ka.question, fonts, true);
          doc
            .font(qFont)
            .fontSize(8.5)
            .fillColor("#475569")
            .text(`Q: "${ka.question}"`, 48, y, { width: contentWidth - 16 });
          y += doc.heightOfString(`Q: "${ka.question}"`, { width: contentWidth - 16 }) + 3;

          const aFont = getFontForText(ka.answer, fonts);
          doc
            .font(aFont)
            .fontSize(8.5)
            .fillColor("#0f172a")
            .text(`A: ${ka.answer}`, 58, y, { width: contentWidth - 26 });
          y += doc.heightOfString(`A: ${ka.answer}`, { width: contentWidth - 26 }) + 6;
        }
        y += 4;
      }

      // 5. Section 3: SafeSteps Guidance & Triage Assessment
      doc
        .font(fonts.bold)
        .fontSize(10.5)
        .fillColor("#0f172a")
        .text("3. SafeSteps Guidance & Triage Assessment", 40, y);

      y += 16;

      // Urgency Box
      const urgencyText = `Urgency Level: ${summary.urgencyLabel}`;
      const urgencyColor =
        summary.guidanceUrgency === "emergency"
          ? "#dc2626"
          : summary.guidanceUrgency === "see_doctor_soon"
          ? "#b45309"
          : "#0f766e";

      const urgencyBg =
        summary.guidanceUrgency === "emergency"
          ? "#fee2e2"
          : summary.guidanceUrgency === "see_doctor_soon"
          ? "#fef3c7"
          : "#ccfbf1";

      const urgBoxHeight = 22;
      doc
        .rect(48, y, contentWidth - 16, urgBoxHeight)
        .fillAndStroke(urgencyBg, urgencyColor);

      doc
        .font(getFontForText(urgencyText, fonts, true))
        .fontSize(8.5)
        .fillColor(urgencyColor)
        .text(urgencyText, 56, y + 6);

      y += urgBoxHeight + 8;

      // Plain Summary
      const summaryFont = getFontForText(summary.plainSummary, fonts);
      doc
        .font(summaryFont)
        .fontSize(8.5)
        .fillColor("#1e293b")
        .text(summary.plainSummary, 48, y, {
          width: contentWidth - 16,
          lineGap: 2,
        });

      y += doc.heightOfString(summary.plainSummary, { width: contentWidth - 16, lineGap: 2 }) + 12;

      // 6. Section 4: Suggested Questions for Your Consultation
      doc
        .font(fonts.bold)
        .fontSize(10.5)
        .fillColor("#0f172a")
        .text("4. Suggested Questions for Your Consultation", 40, y);

      y += 16;

      for (let i = 0; i < summary.doctorQuestions.length; i++) {
        const q = summary.doctorQuestions[i];
        const qFont = getFontForText(q, fonts);

        // Checkbox square
        doc.rect(48, y + 2, 8, 8).strokeColor("#94a3b8").lineWidth(1).stroke();

        const qText = `${i + 1}. ${q}`;
        doc
          .font(qFont)
          .fontSize(8.5)
          .fillColor("#0f172a")
          .text(qText, 62, y, { width: contentWidth - 30 });

        y += doc.heightOfString(qText, { width: contentWidth - 30 }) + 5;
      }

      // 7. Footer (Fixed at page bottom)
      const footerY = 790;
      doc
        .strokeColor("#e2e8f0")
        .lineWidth(0.8)
        .moveTo(40, footerY - 8)
        .lineTo(pageWidth - 40, footerY - 8)
        .stroke();

      // Required verbatim clinical footer
      doc
        .font(fonts.bold)
        .fontSize(8)
        .fillColor("#475569")
        .text(
          "Generated by SafeSteps. General information only, not a medical record or diagnosis.",
          40,
          footerY,
          { align: "center", width: contentWidth }
        );

      doc
        .font(fonts.regular)
        .fontSize(7)
        .fillColor("#94a3b8")
        .text(
          `Record ID: ${consultationRef} • NHS DCB0129 Clinical Safety Aligned • 256-bit Encrypted • Page 1 of 1`,
          40,
          footerY + 12,
          { align: "center", width: contentWidth }
        );

      doc.end();
    } catch (err) {
      reject(err);
    }
  });
}
